import{_ as p,A as c,o as r,c as d,O as n,b as g,w as t,Z as e,E as a,a as i}from"./chunks/framework.2c2d5a61.js";const M=JSON.parse('{"title":"Spring 全家桶","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/04-Spring全家桶.md","filePath":"interview/后端/Java/04-Spring全家桶.md","lastUpdated":1789026500000}'),l={name:"interview/后端/Java/04-Spring全家桶.md"};function S(u,o,h,B,m,b){const s=c("Mermaid");return r(),d("div",null,[o[2]||(o[2]=n('<h1 id="spring-全家桶" tabindex="-1">Spring 全家桶 <a class="header-anchor" href="#spring-全家桶" aria-label="Permalink to &quot;Spring 全家桶&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-ioc-与-di-★★★" tabindex="-1">1. IOC 与 DI ★★★ <a class="header-anchor" href="#_1-ioc-与-di-★★★" aria-label="Permalink to &quot;1. IOC 与 DI ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>IOC</strong> 是思想：对象的创建和依赖由「业务代码自己 new」反转给 <strong>Spring</strong> 容器管。<strong>DI</strong> 是实现手段：容器通过<strong>构造器</strong> / <strong>setter</strong> / <strong>字段</strong>把依赖塞进来。好处是<strong>解耦</strong>、好测试（能注入 mock）。注入方式优先<strong>构造器</strong>（依赖不可变、能暴露<strong>循环依赖</strong>、方便测试），<strong>字段注入</strong>（@Autowired 直接标在字段上）不推荐，因为它隐藏了依赖、<strong>单测</strong>时只能靠反射。</p><p><strong>我的项目关联</strong> 我们所有服务都是 <strong>SpringBoot</strong>，Service 之间全靠<strong>构造器注入</strong>。后台管理服务（yld-admin-service）和 App 服务（yld-app-service）里都是这么写的，不写 <code>new</code>，也好写单测。</p><p><strong>面试答题话术</strong> 「<strong>IOC</strong> 是思想，<strong>DI</strong> 是实现。好处是解耦和好测试。注入方式我优先<strong>构造器注入</strong>，因为依赖是 final 不可变、<strong>循环依赖</strong>能早点暴露、单测直接 new 就行；<strong>字段注入</strong>我不用，隐藏依赖还不好测。项目里 Service 全是构造器注入。」</p><hr><h2 id="_2-beanfactory-与-applicationcontext-★★☆" tabindex="-1">2. BeanFactory 与 ApplicationContext ★★☆ <a class="header-anchor" href="#_2-beanfactory-与-applicationcontext-★★☆" aria-label="Permalink to &quot;2. BeanFactory 与 ApplicationContext ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>BeanFactory</strong> 是最底层容器，<strong>懒加载</strong>，getBean 时才创建，功能少。<strong>ApplicationContext</strong> 继承它，启动时就把<strong>单例 Bean</strong> 全建好（<strong>饿加载</strong>），还提供国际化、事件发布、资源加载、<strong>AOP</strong> 等。生产上用的都是 ApplicationContext。</p><p><strong>我的项目关联</strong> 记结论：平时说的 <strong>Spring 容器</strong>就是 <strong>ApplicationContext</strong>，<strong>SpringBoot</strong> 里也是它。启动慢一点但换来实时可用，这对我们网关这种启动后要立刻扛流量的服务是好事。</p><p><strong>面试答题话术</strong> 「<strong>BeanFactory</strong> 是底层接口，<strong>懒加载</strong>、功能少；<strong>ApplicationContext</strong> 继承它，启动就<strong>预实例化</strong>单例，还多了事件、国际化、资源加载这些。生产用 ApplicationContext，SpringBoot 里内置的就是它。」</p><hr><h2 id="_3-bean-生命周期-★★★" tabindex="-1">3. Bean 生命周期 ★★★ <a class="header-anchor" href="#_3-bean-生命周期-★★★" aria-label="Permalink to &quot;3. Bean 生命周期 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 八步：<strong>实例化</strong>（构造器）→ <strong>属性注入</strong> → Aware 接口回调 → <strong>BeanPostProcessor</strong> 前置 → <strong>初始化</strong>（@PostConstruct → afterPropertiesSet → init-method）→ BeanPostProcessor 后置（<strong>AOP 代理</strong>就在这一步生成）→ 使用 → <strong>销毁</strong>（@PreDestroy → destroy → destroy-method）。重点记两件事：@PostConstruct 比 afterPropertiesSet 先执行；AOP 代理在「后置处理」这一环产生。</p><p><strong>我的项目关联</strong> 我们用它做<strong>初始化</strong>：比如网关启动时要把「协议命令处理器」注册到一张表里，就写在 @PostConstruct 或 afterPropertiesSet 里。<strong>不用深挖 BeanPostProcessor 内部源码</strong>，记住它是「Bean 初始化的<strong>前后钩子</strong>、<strong>AOP</strong> 靠它」就够了。</p><p><strong>面试答题话术</strong> 「<strong>生命周期</strong>核心是：<strong>实例化</strong>、<strong>属性注入</strong>、Aware、初始化前后两个 <strong>BeanPostProcessor</strong>、使用、<strong>销毁</strong>。两个高频点：@PostConstruct 比 InitializingBean 的 afterPropertiesSet 早；<strong>AOP 代理</strong>是在 postProcessAfterInitialization 里生成的。我用它做<strong>启动初始化</strong>，比如把协议处理器注册到本地表。」</p><hr><h2 id="_4-bean-作用域-★★☆" tabindex="-1">4. Bean 作用域 ★★☆ <a class="header-anchor" href="#_4-bean-作用域-★★☆" aria-label="Permalink to &quot;4. Bean 作用域 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 默认 <strong>singleton</strong>（容器里一个），<strong>prototype</strong> 每次拿新的，Web 里还有 request/session/application。有个<strong>坑</strong>：prototype Bean 注入到 singleton Bean 里，只会注入一次，之后不会每次新建——想每次拿新的得用 <code>@Lookup</code> 或注入 <code>ObjectFactory</code>。</p><p><strong>我的项目关联</strong> 我们 99% 是<strong>单例</strong>，<strong>无状态</strong>的 Service 都用默认单例。<strong>prototype</strong> 基本不用，所以那个注入坑属于「通用坑」，没实际踩过，知道有这回事就行。</p><p><strong>面试答题话术</strong> 「默认<strong>单例</strong>，<strong>prototype</strong> 每次新建。坑是 prototype 注入到单例里只注入一次，要每次<strong>新实例</strong>得用 @Lookup 或 ObjectFactory。项目里几乎全用单例。」</p><hr><h2 id="_5-单例-bean-的线程安全-★★★-【简历亮点-高频追问】" tabindex="-1">5. 单例 Bean 的线程安全 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-单例-bean-的线程安全-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 单例 Bean 的线程安全 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>单例 Bean</strong> 只要「<strong>无状态</strong>」（只有方法、没有可变的成员变量）就是<strong>线程安全</strong>的。一旦在单例 Bean 里放了<strong>共享可变字段</strong>（比如一个计数器、一个 Map 当本地缓存），<strong>多线程</strong>访问就出问题。解决办法：尽量无状态；要状态就用 ThreadLocal 隔离，或者用<strong>并发容器</strong> / 原子类；再不行才改 prototype。Controller 默认单例，只要不写可变成员变量就安全，方法里的<strong>局部变量</strong>天然安全。</p><p><strong>我的项目关联</strong><strong>这条我特别有体会。</strong> 网关里有些处理器 Bean 是<strong>单例</strong>的，早期有人在里面写了 <code>private Map</code> 当<strong>本地缓存</strong>，<strong>多线程</strong>一跑数据就乱了（现象是「同一个设备的状态莫名其妙被覆盖」），后来改成 <strong>ConcurrentHashMap</strong> 或者干脆挪到 <strong>Redis</strong> 才解决。<strong>这是真实踩过的坑</strong>，也是我现在写单例 Bean 的铁律：不放<strong>可变字段</strong>。</p><p><strong>面试答题话术</strong> 「<strong>单例 Bean</strong> 只要<strong>无状态</strong>就<strong>线程安全</strong>。我踩过这个坑——网关里一个单例处理器里放了普通 <strong>HashMap</strong> 当缓存，<strong>多线程</strong>下数据互相覆盖，后来换成 ConcurrentHashMap 或者直接放 Redis。所以我的原则是：单例 Bean 不放<strong>共享可变字段</strong>，要状态就用<strong>并发容器</strong>或 <strong>ThreadLocal</strong>。Controller 单例安全也是同一个道理，别写成员变量。」</p><hr><h2 id="_6-循环依赖与三级缓存-★★☆-记结论即可" tabindex="-1">6. 循环依赖与三级缓存 ★★☆（记结论即可） <a class="header-anchor" href="#_6-循环依赖与三级缓存-★★☆-记结论即可" aria-label="Permalink to &quot;6. 循环依赖与三级缓存 ★★☆（记结论即可）&quot;">​</a></h2><p><strong>通俗理解</strong> Spring 用<strong>三级缓存</strong>解决「单例 + 字段/setter 注入」的<strong>循环依赖</strong>：一级放成品 Bean，二级放<strong>提前暴露</strong>的<strong>半成品</strong>，三级放能生成半成品的 ObjectFactory（AOP 场景下保证拿到的是代理）。<strong>结论就三句</strong>：只能解决单例 + setter/字段注入；<strong>构造器注入</strong>的循环依赖解决不了（直接抛 BeanCurrentlyInCreationException）；<strong>SpringBoot 2.6</strong> 之后默认禁止循环依赖，要用得手动开。不用去背三级缓存的逐行流转。</p><p><strong>我的项目关联</strong> 现在基本不让自己写出<strong>循环依赖</strong>——<strong>SpringBoot 2.6</strong> 之后默认就报错了。我们遇到时的处理不是去开开关，而是直接<strong>重构</strong>：把公共逻辑抽到第三个 Bean 里。这属于设计问题，别靠<strong>框架</strong>兜。</p><p><strong>面试答题话术</strong> 「<strong>三级缓存</strong>解决的是单例加 setter/字段注入的<strong>循环依赖</strong>，一级是成品、二级是<strong>提前暴露</strong>的半成品、三级是生成半成品的工厂。结论最重要：<strong>构造器注入</strong>的循环依赖解决不了，而且 <strong>SpringBoot 2.6</strong> 之后默认就禁止循环依赖了。我项目里遇到就直接重构抽公共 Bean，不靠框架兜底。」</p><hr><h2 id="_7-aop-原理-jdk-动态代理-vs-cglib-★★★-【简历亮点-高频追问】" tabindex="-1">7. AOP 原理（JDK 动态代理 vs CGLIB）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-aop-原理-jdk-动态代理-vs-cglib-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. AOP 原理（JDK 动态代理 vs CGLIB）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>AOP</strong> 就是把日志、事务、权限这些「<strong>横切逻辑</strong>」从业务代码里抽出来，用<strong>代理</strong>在方法前后织进去。两种实现：<strong>JDK 动态代理</strong>基于接口（<code>Proxy.newProxyInstance</code>），要求目标有接口；<strong>CGLIB</strong> 基于继承生成子类，不需要接口，但 final 类/方法代理不了。Spring 默认「有接口用 JDK、没接口用 CGLIB」，<strong>SpringBoot 2.x</strong> 起默认直接 CGLIB。</p><p><strong>我的项目关联</strong> 我们用它做统一日志、接口耗时统计、权限校验，还有最关键的——<strong>声明式事务</strong>（@Transactional 本质就是 <strong>AOP</strong>）。<strong>这里有个认知要点</strong>：因为事务是 AOP 实现的，所以它依赖「<strong>走代理</strong>」，同一类内部 <code>this.方法()</code> 调用不走代理、事务就会<strong>失效</strong>。</p><p><strong>面试答题话术</strong> 「<strong>AOP</strong> 是用代理把横切逻辑织进方法前后。<strong>JDK 代理</strong>基于接口，<strong>CGLIB</strong> 基于继承、不需要接口但不能代理 final。SpringBoot 现在默认用 CGLIB。项目里事务、日志、权限都是 AOP 做的。关键认知是：事务靠代理生效，所以 this <strong>自调用</strong>会失效。」</p><hr><h2 id="_8-transactional-失效场景-★★★-【简历亮点-高频追问】" tabindex="-1">8. @Transactional 失效场景 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_8-transactional-失效场景-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;8. @Transactional 失效场景 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 最常见六种<strong>失效</strong>：① 方法不是 public（事务只对 public 生效）；② 同类内部 <code>this.xxx()</code> <strong>自调用</strong>，不走代理；③ 异常被自己 catch 吞了，事务感知不到；④ 抛的是<strong>受检异常</strong>，默认只回滚 RuntimeException/Error，要加 <code>rollbackFor = Exception.class</code>；⑤ 方法所在类不是 <strong>Spring Bean</strong>；⑥ 数据库引擎不支持事务（如 <strong>MyISAM</strong>）。自调用的三种解法：注入自己、<code>AopContext.currentProxy()</code>、或者把方法抽到另一个 Bean。</p><p><strong>我的项目关联</strong><strong>这个坑我们在订单、支付相关逻辑上确实遇到过。</strong> 现象是「内部方法报错了但数据没回滚」，排查发现是同类里的 <code>this.xxx()</code> 调用<strong>绕过了代理</strong>。修复就是把这段逻辑抽到独立的 Service Bean，或者注入自身调。现在团队<strong>规范</strong>是：<strong>事务方法绝不和调用方放同一个类</strong>。</p><p><strong>面试答题话术</strong> 「失效主要有六种：非 public、<strong>自调用</strong>、异常被吞、<strong>受检异常</strong>不回滚、类不是 Bean、引擎不支持事务。最常见的是自调用，因为事务是<strong>代理</strong>实现的，this 调用不走代理。我项目里真遇到过——内部方法报错但没回滚，后来把逻辑抽到独立 Bean 解决。我的规范是：事务方法不和调用方放一个类，受检异常一定加 rollbackFor。」</p><hr><h2 id="_9-事务传播行为-★★★" tabindex="-1">9. 事务传播行为 ★★★ <a class="header-anchor" href="#_9-事务传播行为-★★★" aria-label="Permalink to &quot;9. 事务传播行为 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 七种，重点记两个：<strong>REQUIRED</strong>（默认，有事务就加入，没有就新建，事务内任何一处<strong>回滚</strong>全体回滚）；<strong>REQUIRES_NEW</strong>（永远新建独立事务，把当前事务<strong>挂起</strong>，内层回滚不影响外层）。其余知道名字即可：SUPPORTS、NOT_SUPPORTED、MANDATORY、NEVER、NESTED。</p><p><strong>我的项目关联</strong> 最典型的用法是「主流程失败要回滚，但操作日志必须记下来」——日志那块就用 <strong>REQUIRES_NEW</strong>，保证<strong>主事务回滚</strong>了日志还在。对账、订单主流程用默认 <strong>REQUIRED</strong>。</p><p><strong>面试答题话术</strong> 「七种<strong>传播行为</strong>，重点就两个：<strong>REQUIRED</strong> 是默认，共用事务，一处回滚全回滚；<strong>REQUIRES_NEW</strong> 是独立事务，<strong>挂起</strong>外层，内层回滚不影响外层。项目里操作日志用 REQUIRES_NEW，保证主事务回滚了日志还在，主流程用默认 REQUIRED。」</p><hr><h2 id="_10-springboot-自动配置原理-★★★" tabindex="-1">10. SpringBoot 自动配置原理 ★★★ <a class="header-anchor" href="#_10-springboot-自动配置原理-★★★" aria-label="Permalink to &quot;10. SpringBoot 自动配置原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>@SpringBootApplication</code> = <code>@SpringBootConfiguration</code> + <code>@EnableAutoConfiguration</code> + <code>@ComponentScan</code>。<code>@EnableAutoConfiguration</code> 通过 <code>@Import(AutoConfigurationImportSelector)</code> 去读 <code>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</code>（<strong>2.7</strong> 之后的新位置，老版本才是 <code>spring.factories</code>），拿到一堆<strong>自动配置类</strong>，再用 <code>@ConditionalOnClass</code>、<code>@ConditionalOnMissingBean</code>、<code>@ConditionalOnProperty</code> 判断要不要生效，从而实现「<strong>约定大于配置</strong>」。</p>',50)),(r(),g(e,null,{default:t(()=>[a(s,{id:"mermaid-166",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BEnableAutoConfiguration%5D%20--%3E%20B%5BAutoConfigurationImportSelector%5D%0A%20%20%20%20B%20--%3E%20C%5B%E8%AF%BB%20AutoConfiguration.imports%3Cbr%2F%3E%E6%8B%BF%E5%88%B0%E9%85%8D%E7%BD%AE%E7%B1%BB%E6%B8%85%E5%8D%95%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%9D%A1%E4%BB%B6%E6%B3%A8%E8%A7%A3%E8%BF%87%E6%BB%A4%3Cbr%2F%3EConditionalOnClass%20%E7%AD%89%5D%0A%20%20%20%20D%20--%3E%20E%5B%E6%B3%A8%E5%86%8C%20Bean%20%E5%88%B0%E5%AE%B9%E5%99%A8%5D%0A"})]),fallback:t(()=>o[0]||(o[0]=[i(" Loading... ")])),_:1})),o[3]||(o[3]=n('<p><strong>我的项目关联</strong> 我们写过内部 <strong>starter</strong> 封装<strong>公共能力</strong>（比如统一异常、日志、埋点），就是照着这个套路：写配置类 + 在 imports 文件里注册 + <strong>条件注解</strong>，业务服务引依赖就<strong>自动生效</strong>。<strong>注意</strong>：现在面试要答 <code>AutoConfiguration.imports</code>，老说 <code>spring.factories</code> 会显旧。</p><p><strong>面试答题话术</strong> 「@SpringBootApplication 拆开是配置类、开启<strong>自动配置</strong>、<strong>组件扫描</strong>。自动配置的核心是 @Import 导入 AutoConfigurationImportSelector，读 AutoConfiguration.imports 文件拿到自动配置类，再用 ConditionalOnClass、ConditionalOnMissingBean 这些<strong>条件注解</strong>判断是否生效。注意 <strong>2.7</strong> 之后是 imports 文件，不是老的 spring.factories。我项目里封装公共 <strong>starter</strong> 就是这个套路。」</p><hr><h2 id="_11-springmvc-请求处理流程-★★★" tabindex="-1">11. SpringMVC 请求处理流程 ★★★ <a class="header-anchor" href="#_11-springmvc-请求处理流程-★★★" aria-label="Permalink to &quot;11. SpringMVC 请求处理流程 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 请求先到 <strong>DispatcherServlet</strong>（前端控制器）→ <strong>HandlerMapping</strong> 按 URL 找到对应的方法 → <strong>HandlerAdapter</strong> 执行方法（做参数解析、类型转换、校验）→ 返回 ModelAndView 或者 @ResponseBody 直接写 JSON → <strong>ViewResolver</strong> 解析视图（返回 JSON 就不走这步）→ 响应。</p><p><strong>我的项目关联</strong> 我们基本都是<strong>前后端分离</strong> + <strong>REST 接口</strong>，所以「@ResponseBody 直接返回 JSON」这条路径最多，ViewResolver 基本用不到。参数解析这块我们在自定义注解上做过扩展，所以知道它由 <strong>HandlerAdapter</strong> 里的<strong>参数解析器</strong>负责。</p><p><strong>面试答题话术</strong> 「流程是：请求到 <strong>DispatcherServlet</strong>，<strong>HandlerMapping</strong> 找 Handler，<strong>HandlerAdapter</strong> 执行并处理参数，返回 ModelAndView 或 @ResponseBody 直接写 JSON，最后 <strong>ViewResolver</strong> 解析视图。<strong>前后端分离</strong>的项目基本都走 @ResponseBody 返 JSON，视图解析那步用不上。」</p><hr><h2 id="_12-bean-装配注解区别-★★☆" tabindex="-1">12. Bean 装配注解区别 ★★☆ <a class="header-anchor" href="#_12-bean-装配注解区别-★★☆" aria-label="Permalink to &quot;12. Bean 装配注解区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> @Autowired 是 Spring 的，默认<strong>按类型注入</strong>，配合 @Qualifier <strong>按名字</strong>。@Resource 是 JDK 标准的，默认按名字，找不到再按类型。@Inject 是 <strong>JSR-330</strong> 的，跟 @Autowired 差不多。</p><p><strong>我的项目关联</strong> 一句话：同一个类型有<strong>多个实现</strong>时，我用 @Qualifier 或者 @Resource <strong>按名字</strong>指明。这是<strong>常规用法</strong>，没坑。</p><p><strong>面试答题话术</strong> 「@Autowired 是 Spring 的、默认<strong>按类型</strong>；@Resource 是 JDK 的、默认<strong>按名字</strong>找不到再按类型。多个<strong>同类型实现</strong>时用 @Qualifier 或 @Resource 指定名字。」</p><hr><h2 id="_13-spring、springboot、springcloud-区别-★★★" tabindex="-1">13. Spring、SpringBoot、SpringCloud 区别 ★★★ <a class="header-anchor" href="#_13-spring、springboot、springcloud-区别-★★★" aria-label="Permalink to &quot;13. Spring、SpringBoot、SpringCloud 区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Spring</strong> 是地基：提供 <strong>IOC</strong> 和 <strong>AOP</strong>，但配置繁琐。<strong>SpringBoot</strong> 是脚手架：<strong>自动配置</strong> + 起步依赖 + 内嵌服务器，让搭建变快。<strong>SpringCloud</strong> 是微服务工具集：注册中心、配置中心、网关、服务调用、熔断。一句话：Spring 是地基，SpringBoot 是快速建房，SpringCloud 是城市基础设施。</p><p><strong>我的项目关联</strong> 我们的服务全是 <strong>SpringBoot</strong> 打底，像 yld-tcec <strong>互联互通</strong>、yld-admin-service 后台服务都是独立的 SpringBoot 应用，之间再靠<strong>远程调用</strong>和消息串起来。</p><p><strong>面试答题话术</strong> 「<strong>Spring</strong> 是核心框架，<strong>IOC</strong> 加 <strong>AOP</strong>，但配置麻烦；<strong>SpringBoot</strong> 是它的封装，自动配置加起步依赖，开箱即用；<strong>SpringCloud</strong> 是微服务工具集，管注册、配置、网关、调用、熔断。一句话：Spring 是地基，Boot 是快速建房，Cloud 是城市基础设施。我们项目就是 SpringBoot 应用之间靠远程调用和消息串联。」</p><hr><h2 id="_14-spring-security-鉴权链路-jwt-★★★-【简历亮点-高频追问】" tabindex="-1">14. Spring Security 鉴权链路（JWT）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_14-spring-security-鉴权链路-jwt-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;14. Spring Security 鉴权链路（JWT）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 基于<strong>过滤器链</strong>：请求先过认证和授权的过滤器，再进 Controller。<strong>JWT</strong> 认证流程：请求带 Token → 自定义 JWT 过滤器解析并校验<strong>签名</strong>和<strong>有效期</strong> → 把用户信息塞进 <code>SecurityContextHolder</code> → 后续授权就基于它判断。JWT 是 Header.Payload.Signature 三段 <strong>Base64</strong>，Payload 只放用户 id、角色这些<strong>非敏感信息</strong>。</p><p><strong>我的项目关联</strong> 后台管理端和 App 端都是 <strong>JWT 鉴权</strong>：登录发 token，之后每个请求走 JWT 过滤器。<strong>一个必须讲的坑</strong>：JWT 是<strong>无状态</strong>的，签出去就收不回，没法主动踢人下线——我们的做法是配合 <strong>Redis</strong> 存<strong>黑名单</strong>或者存登录态。另外 JWT 过滤器一定要排在用户名密码过滤器之前，<strong>白名单</strong>（登录、静态资源）要放行。这是通用坑，我们规范上处理了。</p><p><strong>面试答题话术</strong> 「Security 是<strong>过滤器链</strong>，请求先认证再授权。<strong>JWT</strong> 流程是：前端带 token，自定义过滤器解析校验，把用户信息放进 SecurityContextHolder，后面授权基于它。JWT 本身<strong>无状态</strong>、签了收不回，所以踢下线要配合 <strong>Redis 黑名单</strong>。还有<strong>过滤器顺序</strong>要在用户名密码过滤器之前，<strong>白名单</strong>要放行。项目里后台和 App 都是这套。」</p><hr><h2 id="_15-mybatis-一级缓存、二级缓存-★★★" tabindex="-1">15. MyBatis 一级缓存、二级缓存 ★★★ <a class="header-anchor" href="#_15-mybatis-一级缓存、二级缓存-★★★" aria-label="Permalink to &quot;15. MyBatis 一级缓存、二级缓存 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>一级缓存</strong>是 <strong>SqlSession</strong> 级别，默认开，同一个 SqlSession 内相同查询走缓存；SqlSession 关闭或执行增删改就清空。<strong>二级缓存</strong>是 <strong>Mapper</strong>（namespace）级别，跨 SqlSession，需要显式开（<code>cacheEnabled=true</code> + <code>&lt;cache/&gt;</code>），实体要<strong>序列化</strong>。结论：MyBatis 缓存<strong>粒度粗</strong>、分布式下容易读到旧数据，所以<strong>我们线上基本关掉二级缓存，用 Redis 做缓存</strong>。</p><p><strong>我的项目关联</strong> 我们直接关二级缓存。原因很直接：服务是<strong>多实例部署</strong>，二级缓存是「单机」的，A 实例改了数据，B 实例的缓存还是旧的，会读到<strong>脏数据</strong>。缓存统一交给 <strong>Redis</strong>，可控、能<strong>主动失效</strong>。</p><p><strong>面试答题话术</strong> 「<strong>一级缓存</strong>是 <strong>SqlSession</strong> 级、默认开，执行增删改或关闭就清；<strong>二级缓存</strong>是 Mapper 级、跨 SqlSession、要显式开。但二级缓存是<strong>单机</strong>的，<strong>多实例部署</strong>会读到<strong>脏数据</strong>，所以线上我一般关掉，缓存统一用 <strong>Redis</strong>。项目里就是这么做的。」</p><hr><h2 id="_16-mybatis-执行流程-★★☆" tabindex="-1">16. MyBatis 执行流程 ★★☆ <a class="header-anchor" href="#_16-mybatis-执行流程-★★☆" aria-label="Permalink to &quot;16. MyBatis 执行流程 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 配置阶段解析 XML/注解生成 <strong>Configuration</strong> 和 <strong>MappedStatement</strong>；然后开 <strong>SqlSession</strong>，内部建 <strong>Executor</strong>；执行时 Mapper 接口的动态代理找到对应的 MappedStatement，Executor 交给 <strong>StatementHandler</strong> 处理参数、<strong>ResultSetHandler</strong> 把结果映射成对象。插件（<strong>Interceptor</strong>）就是在这几个环节做<strong>动态代理拦截</strong>，分页插件就是这么实现的。</p><p><strong>我的项目关联</strong> 知道流程和「<strong>分页插件</strong>基于 <strong>Interceptor</strong>」这个结论就行，不用背源码。我们用的 <strong>MyBatis-Plus</strong> 分页插件就是这个原理。</p><p><strong>面试答题话术</strong> 「流程是配置解析、开 <strong>SqlSession</strong>、动态代理找到 <strong>MappedStatement</strong>、<strong>Executor</strong> 执行、<strong>StatementHandler</strong> 处理参数、<strong>ResultSetHandler</strong> 映射结果。插件是基于 <strong>Interceptor</strong> 代理这几步，分页插件就是这么做的。」</p><hr><h2 id="_17-mybatis-plus-相比-mybatis-的优势-★★☆" tabindex="-1">17. MyBatis-Plus 相比 MyBatis 的优势 ★★☆ <a class="header-anchor" href="#_17-mybatis-plus-相比-mybatis-的优势-★★☆" aria-label="Permalink to &quot;17. MyBatis-Plus 相比 MyBatis 的优势 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 内置<strong>通用 CRUD</strong>（<strong>BaseMapper</strong>）、条件构造器 <strong>Wrapper</strong>、<strong>分页插件</strong>、<strong>逻辑删除</strong>、字段自动填充、代码生成器，省掉大量<strong>样板 SQL</strong>。本质还是 MyBatis 的增强，底层没变。</p><p><strong>我的项目关联</strong> 我们项目用的就是 <strong>MyBatis-Plus</strong>，简单单表增删改查直接用 <strong>BaseMapper</strong> 和 <strong>Wrapper</strong>，复杂查询才手写 <strong>XML</strong>。逻辑删除、自动填充创建时间这些也都用上了。</p><p><strong>面试答题话术</strong> 「<strong>MP</strong> 就是 <strong>MyBatis</strong> 的增强，内置 CRUD、<strong>Wrapper</strong> 条件构造器、分页、<strong>逻辑删除</strong>、自动填充、代码生成器，省<strong>样板代码</strong>，底层还是 MyBatis。项目里单表操作用它，复杂查询手写 XML。」</p><hr><h2 id="_18-和-区别-必考-★★★" tabindex="-1">18. #{} 和 ${} 区别（必考）★★★ <a class="header-anchor" href="#_18-和-区别-必考-★★★" aria-label="Permalink to &quot;18. #{} 和 ${} 区别（必考）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>#{}</code> 是<strong>预编译占位符</strong>（底层是 <strong>PreparedStatement</strong> 的 <code>?</code>），参数<strong>按值绑定</strong>、自动加引号、能防 <strong>SQL 注入</strong>。<code>${}</code> 是直接<strong>字符串拼接</strong>，不防注入，只能用在表名、列名这种不能预编译的地方，而且必须做<strong>白名单校验</strong>。结论一句话：能用 <code>#{}</code> 绝不用 <code>${}</code>。</p><p><strong>我的项目关联</strong> 我们项目<strong>规范</strong>是禁止 <code>${}</code>，<strong>静态扫描</strong>会拦。只有极少数动态排序字段（比如后台按哪个字段排序）用 <code>${}</code>，而且字段名必须走<strong>白名单校验</strong>。这是<strong>安全底线</strong>。</p><p><strong>面试答题话术</strong> 「#{} 是<strong>预编译占位符</strong>，参数<strong>按值绑定</strong>，<strong>防注入</strong>；${} 是字符串拼接，不防注入。所以能用 #{} 就不用 ${}，只有表名、列名、排序字段这种没法预编译的才用，而且必须<strong>白名单校验</strong>。项目里我们直接禁止 ${}，静态扫描拦住。」</p><hr><h2 id="_19-spring-中的设计模式-★★★" tabindex="-1">19. Spring 中的设计模式 ★★★ <a class="header-anchor" href="#_19-spring-中的设计模式-★★★" aria-label="Permalink to &quot;19. Spring 中的设计模式 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>工厂</strong>（BeanFactory）、<strong>单例</strong>（默认 Bean）、<strong>代理</strong>（AOP）、<strong>模板方法</strong>（JdbcTemplate/RestTemplate）、<strong>观察者</strong>（ApplicationEvent）、适配器（HandlerAdapter）、<strong>策略</strong>（资源处理）。重点能展开的是<strong>代理模式</strong>——AOP 就是它，用来织入事务、日志。</p><p><strong>我的项目关联</strong> 我用得最多的是「<strong>模板方法 + 策略</strong>」：充电桩不同协议的命令处理，用<strong>策略模式</strong>按<strong>协议类型</strong>分发到不同处理器；公共流程用模板方法抽出来，差异部分子类实现。这样加一种新协议只加一个实现类，不动<strong>主流程</strong>。</p><p><strong>面试答题话术</strong> 「Spring 里常见的：<strong>工厂</strong>用 BeanFactory，<strong>单例</strong>是默认 Bean 作用域，<strong>代理</strong>是 AOP，<strong>模板方法</strong>在 JdbcTemplate，<strong>观察者</strong>是事件机制，<strong>适配器</strong>是 HandlerAdapter。我自己在网关里用<strong>策略模式</strong>按协议分发处理器，加新协议只加实现类不动主流程。」</p><hr><h2 id="_20-async-失效原因-★★☆" tabindex="-1">20. @Async 失效原因 ★★☆ <a class="header-anchor" href="#_20-async-失效原因-★★☆" aria-label="Permalink to &quot;20. @Async 失效原因 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 跟<strong>事务失效</strong>一个道理，都是因为「<strong>依赖代理</strong>」：同类 this <strong>自调用</strong>不走代理、方法非 public、类不是 <strong>Spring Bean</strong>、没开 <code>@EnableAsync</code>。解法也一样：抽到另一个 Bean、注入自身、用 <code>AopContext.currentProxy()</code>。</p><p><strong>我的项目关联</strong> 我们<strong>异步任务</strong>用<strong>线程池</strong> + @Async 都行，但记住「<strong>自调用失效</strong>」这一条就够。它和 @Transactional 失效是同一类问题，底层都是 <strong>AOP 代理</strong>。</p><p><strong>面试答题话术</strong> 「@Async <strong>失效</strong>原因跟 @Transactional 一样：<strong>自调用</strong>、非 public、不是 Bean、没开 @EnableAsync。本质是都靠<strong>代理</strong>，this 调用不走代理。解决就是抽到别的 Bean 或注入自身。」</p><hr><h2 id="_21-springmvc-参数校验、全局异常处理-★★☆" tabindex="-1">21. SpringMVC 参数校验、全局异常处理 ★★☆ <a class="header-anchor" href="#_21-springmvc-参数校验、全局异常处理-★★☆" aria-label="Permalink to &quot;21. SpringMVC 参数校验、全局异常处理 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>参数校验</strong>用 <code>@Valid</code>/<code>@Validated</code> 加 <code>@NotNull</code>/<code>@NotBlank</code>/<code>@Size</code>，失败可以全局<strong>统一处理</strong>。<strong>全局异常</strong>用 <code>@RestControllerAdvice</code> + <code>@ExceptionHandler</code>，统一返回<strong>错误结构</strong>，别让<strong>异常堆栈</strong>直接暴露给前端。</p><p><strong>我的项目关联</strong> 我们统一用 <code>@RestControllerAdvice</code> 做<strong>全局异常</strong>，所有接口返回统一的 <code>code/message/data</code> 结构，<strong>参数校验</strong>失败、<strong>业务异常</strong>、<strong>系统异常</strong>都在这里<strong>收口</strong>。这样前端处理统一，也不会把栈信息漏出去。</p><p><strong>面试答题话术</strong> 「<strong>参数校验</strong>用 @Valid 加注解，失败抛异常。<strong>全局异常</strong>用 @RestControllerAdvice 加 @ExceptionHandler <strong>统一处理</strong>，返回统一结构。项目里所有接口的返回结构、<strong>参数校验错误</strong>、<strong>系统异常</strong>都在一个 Advice 里<strong>收口</strong>，避免把<strong>堆栈</strong>暴露给前端。」</p><hr><h2 id="_22-spring-cloud-核心组件-★★★" tabindex="-1">22. Spring Cloud 核心组件 ★★★ <a class="header-anchor" href="#_22-spring-cloud-核心组件-★★★" aria-label="Permalink to &quot;22. Spring Cloud 核心组件 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>注册中心</strong>（Nacos/Eureka）、<strong>配置中心</strong>（Nacos Config）、<strong>网关</strong>（Spring Cloud Gateway）、<strong>服务调用</strong>（OpenFeign）、<strong>熔断限流</strong>（Sentinel/Resilience4j）、<strong>负载均衡</strong>（LoadBalancer）、<strong>链路追踪</strong>（Sleuth+Zipkin 或 SkyWalking）。<strong>Nacos</strong> 比 Eureka 强在「注册 + 配置一体，还支持 CP/AP 切换」。</p><p><strong>我的项目关联</strong> 我们的服务是<strong>分布式部署</strong>的，服务间调用、注册发现、配置管理都是这套。<strong>要说清楚一点</strong>：我们不是那种「<strong>重微服务</strong>」架构，服务数量有限，所以没用全套 Spring Cloud 组件，主要是<strong>按需</strong>用的注册和调用，别吹成全套 Cloud 微服务体系。</p><p><strong>面试答题话术</strong> 「核心组件：<strong>注册中心</strong>、<strong>配置中心</strong>、<strong>网关</strong>、服务调用、<strong>熔断限流</strong>、<strong>负载均衡</strong>、<strong>链路追踪</strong>。<strong>Nacos</strong> 跟 Eureka 比是注册加配置一体，还能切 CP/AP。项目里我用的是注册发现加远程调用为主，没上全套 Cloud，够用就行。」</p><hr><h2 id="_23-网关作用、gateway-过滤器-★★☆" tabindex="-1">23. 网关作用、Gateway 过滤器 ★★☆ <a class="header-anchor" href="#_23-网关作用、gateway-过滤器-★★☆" aria-label="Permalink to &quot;23. 网关作用、Gateway 过滤器 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>API 网关</strong>的作用：<strong>统一入口</strong>、<strong>路由转发</strong>、<strong>鉴权</strong>、<strong>限流</strong>、日志、灰度。Spring Cloud Gateway 基于 <strong>WebFlux</strong>（响应式、非阻塞），过滤器分全局 GlobalFilter 和局部 GatewayFilter，断言 Predicate 按路径、方法、header 匹配路由。</p><p><strong>我的项目关联</strong><strong>注意别和我们的「协议网关」混了</strong>：Spring Cloud Gateway 是 HTTP 层的 <strong>API 网关</strong>；我们说的充电桩网关是基于 <strong>Netty</strong> 的 <strong>TCP 长连接网关</strong>。面试时要说清这两个是完全不同的东西，不要一被问「网关」就只说 Netty。</p><p><strong>面试答题话术</strong> 「<strong>API 网关</strong>做<strong>统一入口</strong>、<strong>路由</strong>、<strong>鉴权</strong>、<strong>限流</strong>。Gateway 基于 <strong>WebFlux</strong> 是<strong>非阻塞</strong>的，过滤器分全局和局部，断言按路径方法匹配。这里我要区分一下：Spring Cloud Gateway 是 HTTP 层网关，我们项目里还有个基于 <strong>Netty</strong> 的 TCP 协议网关接充电桩，两个不是一回事。」</p><hr><h2 id="_24-微服务架构的优缺点-★★☆" tabindex="-1">24. 微服务架构的优缺点 ★★☆ <a class="header-anchor" href="#_24-微服务架构的优缺点-★★☆" aria-label="Permalink to &quot;24. 微服务架构的优缺点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 优点：<strong>独立部署</strong>、<strong>故障隔离</strong>、可独立扩展、技术栈灵活。缺点：<strong>分布式复杂度</strong>上来了——事务、<strong>一致性</strong>、网络、链路追踪、运维都变难。业务复杂、团队大才值得拆，小项目别硬上<strong>微服务</strong>。</p><p><strong>我的项目关联</strong> 我们按业务拆成了后台服务、App 服务、互联互通服务这些，好处是某个服务出问题不至于全挂；代价是<strong>跨服务调用</strong>和<strong>对账一致性</strong>要额外处理（我们靠消息、<strong>幂等</strong>、<strong>对账补偿</strong>来兜）。</p><p><strong>面试答题话术</strong> 「优点是<strong>独立部署</strong>、<strong>故障隔离</strong>、可扩展；缺点是<strong>分布式复杂度</strong>高，事务、<strong>一致性</strong>、网络、运维都难。项目里我们按业务拆了后台、App、互联互通几个服务，好处是隔离，代价是跨服务一致性要靠消息、<strong>幂等</strong>和<strong>对账补偿</strong>来兜。」</p><hr><h2 id="_25-spring-有哪些模块-★★☆" tabindex="-1">25. Spring 有哪些模块 ★★☆ <a class="header-anchor" href="#_25-spring-有哪些模块-★★☆" aria-label="Permalink to &quot;25. Spring 有哪些模块 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>核心容器</strong>（Beans、Core、Context、SpEL，是 <strong>IOC</strong> 基础）、<strong>AOP</strong>、<strong>数据访问</strong>（JDBC、ORM、事务）、Web（MVC、WebFlux）、测试。SpringBoot 和 SpringCloud 都是在它之上的<strong>扩展</strong>。</p><p><strong>我的项目关联</strong> 一句话：真正的地基是「<strong>核心容器 + AOP</strong>」，其他都是<strong>按需要加</strong>。我们主要用 Web（MVC）、数据访问（MyBatis 整合 + 事务）、<strong>AOP</strong>。</p><p><strong>面试答题话术</strong> 「核心模块是<strong>核心容器</strong>加 <strong>AOP</strong>，其他是<strong>数据访问</strong>、Web、测试。Boot 和 Cloud 都是在 Spring 之上的<strong>扩展</strong>。项目里主要用 MVC、MyBatis 整合和事务、AOP 这几块。」</p><hr><h2 id="_26-spring-有哪些优点-★★☆" tabindex="-1">26. Spring 有哪些优点 ★★☆ <a class="header-anchor" href="#_26-spring-有哪些优点-★★☆" aria-label="Permalink to &quot;26. Spring 有哪些优点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 轻量、<strong>非侵入</strong>（POJO 不用继承 Spring 的类）、<strong>IOC 解耦</strong>、<strong>AOP 解耦横切逻辑</strong>、<strong>声明式事务</strong>、<strong>模板类</strong>简化开发、生态大、方便测试。</p><p><strong>我的项目关联</strong> 一句话：最实在的两个好处是「<strong>声明式事务</strong>」和「<strong>生态整合</strong>」——加个<strong>依赖注解</strong>就整合好 MyBatis、Redis、Kafka，不用自己搓。</p><p><strong>面试答题话术</strong> 「优点：轻量<strong>非侵入</strong>、<strong>IOC 解耦</strong>、<strong>AOP 解耦横切逻辑</strong>、<strong>声明式事务</strong>、<strong>模板类</strong>简化代码、生态大、好测试。最实在的是整合方便，加个 <strong>starter</strong> 就把 MyBatis、Redis、Kafka 串起来了。」</p><hr><h2 id="_27-xml-时代的自动装配模式-byname-autodetect-等-★☆☆-已过时-一句话" tabindex="-1">27. XML 时代的自动装配模式（byName / autodetect 等）★☆☆（已过时，一句话） <a class="header-anchor" href="#_27-xml-时代的自动装配模式-byname-autodetect-等-★☆☆-已过时-一句话" aria-label="Permalink to &quot;27. XML 时代的自动装配模式（byName / autodetect 等）★☆☆（已过时，一句话）&quot;">​</a></h2><p><strong>通俗理解</strong><code>byName</code>、<code>byType</code>、<code>constructor</code>、<code>autodetect</code> 是 <strong>XML 配置时代</strong>的<strong>自动装配模式</strong>，<code>autodetect</code> 早在 Spring 3 就<strong>废弃</strong>了。现在一律用注解：<code>@Autowired</code> 默认按类型、<code>@Resource</code> 默认按名字。<strong>这条面试基本不问，知道「这是老东西、已被注解取代」就够了。</strong></p><hr><h2 id="_28-springboot-启动流程-★★★" tabindex="-1">28. SpringBoot 启动流程 ★★★ <a class="header-anchor" href="#_28-springboot-启动流程-★★★" aria-label="Permalink to &quot;28. SpringBoot 启动流程 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> main 方法创建 <strong>SpringApplication</strong> → 推断应用类型（Servlet 还是 Reactive）→ 加载初始化器和监听器 → 准备 Environment（加载配置、命令行参数、profile）→ 创建 <strong>ApplicationContext</strong> → <strong>refresh</strong> 刷新（扫描 Bean、执行<strong>自动配置</strong>）→ 启动内嵌的 <strong>Tomcat</strong> → 发布 ApplicationReadyEvent。</p><p><strong>我的项目关联</strong> 知道「<strong>refresh 阶段</strong>才会<strong>自动配置</strong>、内嵌 <strong>Tomcat</strong> 是自动配置里创建的」这个结论就行。实际排障时有个用处：启动卡住或 <strong>Bean 冲突</strong>，看日志基本卡在 refresh 阶段。</p><p><strong>面试答题话术</strong> 「流程是：创建 <strong>SpringApplication</strong>、推断应用类型、准备 Environment、创建 <strong>ApplicationContext</strong>、<strong>refresh</strong> 扫描并<strong>自动配置</strong>、启动内嵌 <strong>Tomcat</strong>、发就绪事件。重点知道两件事：自动配置发生在 refresh 阶段，内嵌 Tomcat 也是自动配置里建的。」</p><hr><h2 id="_29-springboot-核心注解-★★★" tabindex="-1">29. SpringBoot 核心注解 ★★★ <a class="header-anchor" href="#_29-springboot-核心注解-★★★" aria-label="Permalink to &quot;29. SpringBoot 核心注解 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>@SpringBootApplication</code> = <code>@SpringBootConfiguration</code> + <code>@EnableAutoConfiguration</code> + <code>@ComponentScan</code>。<strong>条件装配三件套</strong>：<code>@ConditionalOnClass</code>（类在才<strong>生效</strong>）、<code>@ConditionalOnMissingBean</code>（没有这个 Bean 才生效）、<code>@ConditionalOnProperty</code>（配置满足才生效）。<code>@Configuration</code>+<code>@Bean</code> 用来<strong>声明 Bean</strong>，<code>@Component/@Service/@Repository/@Controller</code> 靠<strong>组件扫描</strong>。</p><p><strong>我的项目关联</strong> 我们自定义 <strong>starter</strong> 或者做<strong>条件化配置</strong>时就用这三个<strong>条件注解</strong>，比如「只有当业务方引入了某个依赖、且没自己定义 Bean 时，才注入我们的<strong>默认实现</strong>」。</p><p><strong>面试答题话术</strong> 「@SpringBootApplication 拆开是配置类、开启<strong>自动配置</strong>、<strong>组件扫描</strong>三个。自动配置靠 @Import 导入选择器。<strong>条件装配</strong>最关键的是 @ConditionalOnClass、@ConditionalOnMissingBean、@ConditionalOnProperty，我们封装 <strong>starter</strong> 时就靠这三个控制<strong>生效条件</strong>。」</p><hr><h2 id="_30-mybatis-sqlsession-的线程安全问题-★★★" tabindex="-1">30. MyBatis SqlSession 的线程安全问题 ★★★ <a class="header-anchor" href="#_30-mybatis-sqlsession-的线程安全问题-★★★" aria-label="Permalink to &quot;30. MyBatis SqlSession 的线程安全问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>SqlSession</strong> 不是<strong>线程安全</strong>的：它对应一个数据库连接 + 一个<strong>一级缓存</strong>，多线程共享会互相污染。所以每次操作要用一个新的、用完关闭。跟 Spring 整合后就不用担心了——Mapper 代理是单例，但内部通过 <strong>SqlSessionTemplate</strong> 用 <strong>ThreadLocal</strong> 给每个线程绑定独立的 SqlSession。</p><p><strong>我的项目关联</strong> 我们直接用 Spring 整合的 <strong>Mapper</strong>，从来不手动开 <strong>SqlSession</strong>，所以这个坑碰不到。但面试问「Mapper 是<strong>单例</strong>的为什么不冲突」，答「底层 SqlSessionTemplate 用 <strong>ThreadLocal</strong> 给每个线程独立的 SqlSession」就对了。</p><p><strong>面试答题话术</strong> 「<strong>SqlSession</strong> 非<strong>线程安全</strong>，因为它绑定连接和<strong>一级缓存</strong>，多线程共享会污染。Spring 整合后 Mapper 代理虽然是单例，但底层用 <strong>SqlSessionTemplate</strong> 加 <strong>ThreadLocal</strong>，每个线程拿到独立的 SqlSession，所以安全。项目里我们只用 Mapper，不手写 SqlSession。」</p><hr><h2 id="_31-mybatis-的优缺点-★★☆" tabindex="-1">31. MyBatis 的优缺点 ★★☆ <a class="header-anchor" href="#_31-mybatis-的优缺点-★★☆" aria-label="Permalink to &quot;31. MyBatis 的优缺点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 优点：<strong>SQL 和代码分离</strong>、可手写复杂 SQL、<strong>动态 SQL</strong> 灵活、<strong>轻量无侵入</strong>、插件扩展好。缺点：SQL 依赖<strong>数据库方言</strong>、迁移要改 SQL、样板代码多、<strong>缓存粒度粗</strong>、复杂关联还得手写 join。</p><p><strong>我的项目关联</strong> 选它就是看中「<strong>SQL 可控</strong>」——充电业务里统计、对账、按条件查订单这些复杂查询，要求能<strong>精确调优</strong>，手写 SQL 比 <strong>ORM</strong> 生成的更可控。</p><p><strong>面试答题话术</strong> 「MyBatis 优点是 <strong>SQL 可控</strong>、能写复杂查询和<strong>动态 SQL</strong>、轻量、插件扩展好；缺点是依赖<strong>数据库方言</strong>、样板代码多、<strong>缓存粒度粗</strong>。选它是因为我们业务里对账、统计这种复杂查询要求 SQL 可控、能<strong>精确调优</strong>。」</p><hr><h2 id="_32-springboot-的-starter-机制及自定义-starter-★★★" tabindex="-1">32. SpringBoot 的 starter 机制及自定义 starter ★★★ <a class="header-anchor" href="#_32-springboot-的-starter-机制及自定义-starter-★★★" aria-label="Permalink to &quot;32. SpringBoot 的 starter 机制及自定义 starter ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>starter</strong> 就是一个「<strong>开箱即用的依赖包</strong>」，把某个功能需要的所有 jar 依赖 + 自动配置类打包在一起。你只要引一个 <code>spring-boot-starter-web</code>，它就把 SpringMVC、内嵌 Tomcat、Jackson 这些依赖和默认配置全带上了。<strong>命名规范</strong>：官方叫 <code>spring-boot-starter-xxx</code>，第三方自定义叫 <code>xxx-spring-boot-starter</code>（前缀位置相反，一眼区分官方还是第三方）。自定义 starter 套路就三步：写一个 <code>@Configuration</code> 配置类 + 在 <code>META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports</code> 里注册 + 用 <code>@ConditionalOnXxx</code> 控制<strong>生效条件</strong>，业务方引依赖就自动生效。</p><p><strong>我的项目关联</strong> 我们项目里把<strong>公共能力</strong>抽成了内部 common 模块（common-core、common-redis、common-mybatis），统一异常、日志、埋点这些就是按 <strong>starter 套路</strong>封装的：写配置类 + 在 imports 文件注册 + <strong>条件注解</strong>，各业务服务（互联互通、订单、支付）引依赖就自动生效，不用每个服务重复写。<strong>注意</strong>：<strong>SpringBoot 3.x</strong> 下自动配置注册位置就是 <code>AutoConfiguration.imports</code>，不是老的 <code>spring.factories</code>，面试答错了显旧。</p><p><strong>面试答题话术</strong> 「<strong>starter</strong> 就是打包了依赖和自动配置的『开箱即用』包，引一个 starter 就把整个功能的依赖和默认配置带进来。<strong>命名</strong>上官方是 spring-boot-starter-xxx，第三方反过来是 xxx-spring-boot-starter。<strong>自定义 starter</strong> 三步：写配置类、在 AutoConfiguration.imports 里注册、用 ConditionalOnXxx 控制<strong>生效条件</strong>。我们项目里就把公共能力封装成内部 starter，各服务引依赖自动生效，注意 3.x 是 imports 文件不是老的 spring.factories。」</p><hr><h2 id="_33-springboot-的父依赖-spring-boot-starter-parent-的作用-★★☆" tabindex="-1">33. SpringBoot 的父依赖 spring-boot-starter-parent 的作用 ★★☆ <a class="header-anchor" href="#_33-springboot-的父依赖-spring-boot-starter-parent-的作用-★★☆" aria-label="Permalink to &quot;33. SpringBoot 的父依赖 spring-boot-starter-parent 的作用 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><code>spring-boot-starter-parent</code> 是 SpringBoot 提供的「<strong>父 POM</strong>」，作用三块：① <strong>依赖版本管理</strong>——它继承了 <code>spring-boot-dependencies</code>（<strong>BOM</strong>），把几乎所有常用依赖的版本锁定好，你引 starter 不用写版本号；② 默认插件配置——打包、编译插件、资源过滤都配好，还指定了 Java 版本；③ 默认配置——UTF-8 编码、properties 里可用 <code>@xxx@</code> 占位符替换等。核心一句话：统一管版本，避免<strong>版本冲突</strong>。</p><p><strong>我的项目关联</strong> 我们项目没直接用 spring-boot-starter-parent 当 parent，而是在根 pom 的 dependencyManagement 里直接 import 了 <code>spring-boot-dependencies</code> 这个 <strong>BOM</strong>，还叠加了自己的 yld-tcec-common-bom、mybatis-plus-bom。效果和 parent 继承的<strong>版本管理</strong>一样：引 starter、MySQL、Redis、Kafka、MyBatis-Plus 都不用写版本号，版本统一由 BOM 管。区别只是没继承 parent 里的<strong>默认插件配置</strong>，插件我们在根 pom 自己配。面试时可以顺带说一句「parent 的本质就是 BOM 管版本」。</p><p><strong>面试答题话术</strong> 「spring-boot-starter-parent 主要三件事：统一<strong>依赖版本</strong>（继承 spring-boot-dependencies 这个 <strong>BOM</strong>）、提供<strong>默认插件配置</strong>、给默认编码和编译级别。最大好处是引 starter 不用写版本号，<strong>版本统一</strong>不冲突。我们项目里是直接 import 这个 BOM 到 dependencyManagement，效果一样，引 MySQL、Redis、MyBatis-Plus 都不写版本，插件自己在根 pom 配。」</p><hr><h2 id="_34-springboot-中读取配置的几种方式-value、-configurationproperties、environment-★★★" tabindex="-1">34. SpringBoot 中读取配置的几种方式（@Value、@ConfigurationProperties、Environment）★★★ <a class="header-anchor" href="#_34-springboot-中读取配置的几种方式-value、-configurationproperties、environment-★★★" aria-label="Permalink to &quot;34. SpringBoot 中读取配置的几种方式（@Value、@ConfigurationProperties、Environment）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 三种：① <code>@Value(&quot;${key}&quot;)</code> 读单个值，支持默认值 <code>@Value(&quot;${key:default}&quot;)</code> 和 <strong>SpEL</strong>；② <code>@ConfigurationProperties(prefix=&quot;xxx&quot;)</code> 把一组配置<strong>批量绑定</strong>到 POJO 类，需配合 <code>@Component</code> 或 <code>@EnableConfigurationProperties</code> 注册成 Bean；③ 注入 <code>Environment</code> 对象，用 <code>environment.getProperty(&quot;key&quot;)</code> 手动读，适合运行时动态读或非 Bean 场景。<strong>配置优先级</strong>：<strong>命令行参数</strong> &gt; <strong>环境变量</strong> &gt; <code>application-{profile}.yml</code> &gt; <code>application.yml</code>（命令行最高）。</p><p><strong>我的项目关联</strong> 我们项目里：<strong>零散开关</strong>用 @Value；一组<strong>业务配置</strong>（支付参数、对账阈值、互联互通地址）用 @ConfigurationProperties 绑定成<strong>配置类</strong>，结构化、还能启动时校验必填项；Environment 在工具类或非 Bean 场景手动读。Docker 部署时我们常靠<strong>环境变量覆盖</strong>配置（优先级高于 application.yml），这也对应上面那条优先级规则。</p><p><strong>面试答题话术</strong> 「读配置三种方式：@Value 读单个值、还能设默认值和 SpEL；@ConfigurationProperties 按前缀把一组配置<strong>批量绑定</strong>到 POJO；Environment 手动 getProperty 运行时读。项目里零散开关用 @Value，一组业务配置用 @ConfigurationProperties 绑定成配置类注入，Environment 用在非 Bean 或工具类。<strong>优先级</strong>命令行最高，然后<strong>环境变量</strong>，再到 profile 配置和主配置，Docker 部署就靠环境变量覆盖配置。」</p><hr><h2 id="_35-configurationproperties-与-value-的区别-★★★" tabindex="-1">35. @ConfigurationProperties 与 @Value 的区别 ★★★ <a class="header-anchor" href="#_35-configurationproperties-与-value-的区别-★★★" aria-label="Permalink to &quot;35. @ConfigurationProperties 与 @Value 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>@ConfigurationProperties</code>：<strong>批量绑定</strong>，按 prefix 前缀把一组配置映射到 POJO 字段，支持<strong>松散绑定</strong>（<code>user-name</code>、<code>userName</code>、<code>USER_NAME</code> 都能绑到 userName 字段）、支持绑定 List/Map <strong>复杂类型</strong>、支持 <code>@Validated</code> 校验。<code>@Value</code>：只能单个属性逐个读，支持 <strong>SpEL</strong> 和默认值，但<strong>不支持松散绑定、不支持批量、不支持复杂类型</strong>，校验也不方便。结论：一组<strong>结构化配置</strong>用 @ConfigurationProperties，零散几个值用 @Value。</p><p><strong>我的项目关联</strong> 我们项目里一组业务配置（支付、对账、互联互通）都封装成 @ConfigurationProperties <strong>配置类</strong>，结构化还能在启动时用 @Validated <strong>校验必填项</strong>，避免配置漏填、上线才炸。@Value 只用在<strong>零散开关</strong>上。这是我们在多服务、多配置下的实际用法。</p><p><strong>面试答题话术</strong> 「区别：@ConfigurationProperties 是<strong>批量绑定</strong>，按前缀把一组配置映射到 POJO，支持<strong>松散绑定</strong>、<strong>复杂类型</strong>和 @Validated 校验；@Value 只能单个读，支持 SpEL 和默认值，但不支持松散绑定和复杂类型。项目里一组业务配置我封装成 @ConfigurationProperties 类，结构化还能启动校验必填，@Value 只用在<strong>零散开关</strong>。」</p><hr><h2 id="_36-springboot-启动时会扫描哪些包、如何自定义扫描路径-★★☆" tabindex="-1">36. SpringBoot 启动时会扫描哪些包、如何自定义扫描路径 ★★☆ <a class="header-anchor" href="#_36-springboot-启动时会扫描哪些包、如何自定义扫描路径-★★☆" aria-label="Permalink to &quot;36. SpringBoot 启动时会扫描哪些包、如何自定义扫描路径 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>默认扫描</strong>「启动类所在包及其所有子包」——因为 @SpringBootApplication 里的 @ComponentScan 没指定 basePackages，就默认扫启动类所在包。所以启动类一般放项目<strong>根包</strong>，保证所有 @Component/@Service/@Controller 都被扫到。<strong>自定义扫描</strong>：<code>@SpringBootApplication(scanBasePackages = &quot;com.xxx&quot;)</code> 或 <code>@ComponentScan(basePackages = {...})</code>，也可以用 <code>scanBasePackageClasses</code> 按类定位。注意：纯 MyBatis 的 Mapper 接口 @ComponentScan 扫不到，要单独 <strong>@MapperScan</strong> 指定包。</p><p><strong>我的项目关联</strong> 我们每个微服务的启动类都放在<strong>包根</strong>，所有模块都在其子包下，<strong>默认扫描</strong>就覆盖了，几乎不手写 scanBasePackages。<strong>通用坑</strong>：Mapper 接口默认 @ComponentScan 不认，我们统一在启动类或配置类上加 <strong>@MapperScan</strong> 指定 mapper 包，否则报「找不到 Mapper Bean」。这是我们<strong>规范</strong>里定好的，属于通用坑，不是线上踩出来的。</p><p><strong>面试答题话术</strong> 「<strong>默认扫</strong>启动类所在包及所有子包，所以启动类一般放<strong>根包</strong>。要<strong>自定义</strong>就用 scanBasePackages 或 @ComponentScan 指定。注意 MyBatis 的 Mapper 接口默认扫不到，要单独加 <strong>@MapperScan</strong> 指定包。项目里启动类都放包根，Mapper 统一用 @MapperScan 扫。」</p><hr><h2 id="_37-springboot-支持哪些日志框架、如何切换日志实现-★★☆" tabindex="-1">37. SpringBoot 支持哪些日志框架、如何切换日志实现 ★★☆ <a class="header-anchor" href="#_37-springboot-支持哪些日志框架、如何切换日志实现-★★☆" aria-label="Permalink to &quot;37. SpringBoot 支持哪些日志框架、如何切换日志实现 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> SpringBoot 默认用 <strong>SLF4J</strong>（<strong>门面</strong>）+ <strong>Logback</strong>（实现）。SLF4J 是门面，负责统一 API，实现可以换。SpringBoot 内置 Logback 是默认实现，也支持 Log4j2（引 <code>spring-boot-starter-log4j2</code> 并排除默认的 logback）。<strong>日志级别</strong>：TRACE &lt; DEBUG &lt; INFO &lt; WARN &lt; ERROR。配置项：<code>logging.level.包名=级别</code>、<code>logging.file.name</code>、<code>logging.pattern.xxx</code>。<strong>换实现</strong>就是「排除 logback + 引入 log4j2 starter」。</p><p><strong>我的项目关联</strong> 我们统一用 SLF4J + Logback（默认）。有个细节：根 pom 里引入第三方 starter（比如阿里的 schedulerx2）时，会把它自带的 log4j-api/log4j-core <strong>排除</strong>掉，避免<strong>日志框架打架</strong>，全部走 SLF4J 门面。<strong>日志级别</strong>按包在配置里调，网关、对账这类关键服务线上 INFO，排查临时调 DEBUG。没换过 Log4j2，知道「排除 logback + 引入 log4j2 starter」的换法即可。</p><p><strong>面试答题话术</strong> 「SpringBoot 默认是 <strong>SLF4J 门面</strong>加 <strong>Logback</strong> 实现，支持换 Log4j2，做法是排除 logback 依赖、引入 spring-boot-starter-log4j2。<strong>日志级别</strong>从 TRACE 到 ERROR，配置项有 logging.level、logging.file.name。项目里用默认 Logback，还会把第三方 starter 自带的 log4j 排除掉，避免日志框架打架，关键服务线上 INFO，排查再临时开 DEBUG。」</p><hr><h2 id="_38-springboot-的内置容器有哪些、如何替换-★★☆" tabindex="-1">38. SpringBoot 的内置容器有哪些、如何替换 ★★☆ <a class="header-anchor" href="#_38-springboot-的内置容器有哪些、如何替换-★★☆" aria-label="Permalink to &quot;38. SpringBoot 的内置容器有哪些、如何替换 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> SpringBoot 默认内置 <strong>Tomcat</strong>，也支持 <strong>Jetty</strong>、<strong>Undertow</strong>（都是 <strong>Servlet 容器</strong>，WebFlux 场景用 Netty）。<strong>内嵌容器</strong>好处：打成 jar 直接 <code>java -jar</code> 跑，不用外部装 Tomcat。替换方式：在 starter-web 里排除默认 tomcat，再引入对应的 starter（<code>spring-boot-starter-jetty</code> / <code>spring-boot-starter-undertow</code>）。三者对比：Tomcat 生态最大最稳；Jetty 轻量、适合<strong>长连接</strong>；Undertow 性能好、内存占用低。生产主流还是 Tomcat。</p><p><strong>我的项目关联</strong> 我们所有微服务都打成 jar 用 Docker 容器部署，<strong>内嵌 Tomcat</strong> 直接跑，不依赖外部容器。<strong>要区分清楚</strong>：这是 HTTP 层的 <strong>Servlet 容器</strong>；我们充电桩协议网关是基于 Netty 的 <strong>TCP 长连接</strong>服务，跟内置 Web 容器是两码事，别混着说。替换场景我们没做过，默认 Tomcat 够用。</p><p><strong>面试答题话术</strong> 「SpringBoot 默认内嵌 <strong>Tomcat</strong>，也支持 <strong>Jetty</strong> 和 <strong>Undertow</strong>，替换就是排除 tomcat 依赖再引对应的 starter。<strong>内嵌容器</strong>好处是打成 jar 直接 java -jar 跑。项目里全是 jar 加 Docker 部署，内嵌 Tomcat 直接跑。补充一下，我们充电桩协议网关是 Netty 的 <strong>TCP 长连接</strong>，跟这个 Web 容器不是一回事。」</p><hr><h2 id="_39-springboot-中如何实现-bean-的注入方式-构造器-setter-字段-bean-★★★" tabindex="-1">39. SpringBoot 中如何实现 Bean 的注入方式（构造器/Setter/字段/@Bean）★★★ <a class="header-anchor" href="#_39-springboot-中如何实现-bean-的注入方式-构造器-setter-字段-bean-★★★" aria-label="Permalink to &quot;39. SpringBoot 中如何实现 Bean 的注入方式（构造器/Setter/字段/@Bean）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 四种：① <strong>构造器注入</strong>（最推荐）：依赖写在构造器参数里，<strong>final 不可变</strong>、依赖明确、便于测试，Spring 4.3 之后单个构造器可省略 @Autowired；② <strong>Setter 注入</strong>：可选依赖用，可重新赋值；③ <strong>字段注入</strong>（@Autowired 直接标字段，不推荐）：隐藏依赖、不好测试、可能循环依赖；④ @Bean 方法注入：在 @Configuration 里用 @Bean 显式声明 Bean，适合第三方类、需要自定义构造逻辑的场景。<strong>推荐顺序</strong>：构造器 &gt; Setter &gt; 字段。</p><p><strong>我的项目关联</strong> 我们项目 Service 之间统一<strong>构造器注入</strong>（依赖 final 不可变、单测好写），<strong>第三方组件</strong>（客户端、线程池等）用 @Bean 在<strong>配置类</strong>里显式声明。字段注入基本被团队规范禁止。这是<strong>代码规范</strong>，也是能顺手讲出「为什么」的点。</p><p><strong>面试答题话术</strong> 「注入方式四种：<strong>构造器注入</strong>、<strong>Setter</strong>、<strong>字段注入</strong>、@Bean。我优先构造器注入，依赖 final 不可变、依赖明确、好测试，单个构造器还能省略 @Autowired；Setter 用于<strong>可选依赖</strong>；字段注入不推荐，隐藏依赖还不好测；@Bean 用来显式声明第三方类或需要自定义构造逻辑的 Bean。项目里 Service 全部构造器注入，第三方组件走 @Bean。」</p><hr><h2 id="_40-springboot-的-actuator-是什么、常用端点-★★☆" tabindex="-1">40. SpringBoot 的 actuator 是什么、常用端点 ★★☆ <a class="header-anchor" href="#_40-springboot-的-actuator-是什么、常用端点-★★☆" aria-label="Permalink to &quot;40. SpringBoot 的 actuator 是什么、常用端点 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>actuator</strong> 是 SpringBoot 的「<strong>应用监控探针</strong>」，引 <code>spring-boot-starter-actuator</code> 就暴露一堆 <strong>HTTP 端点</strong>，能看应用健康、内存、线程、配置等。常用端点：<code>/actuator/health</code>（<strong>健康检查</strong>，探活用）、<code>/actuator/info</code>（应用信息）、<code>/actuator/metrics</code>（指标，如 JVM 内存、HTTP 请求数）、<code>/actuator/env</code>（环境配置）、<code>/actuator/beans</code>（容器里的 Bean）、<code>/actuator/loggers</code>（动态改日志级别）、<code>/actuator/mappings</code>（接口映射）。<strong>安全要点</strong>：默认只暴露 health 和 info，其他端点要 <code>management.endpoints.web.exposure.include=*</code> 才开，而且不能裸奔，必须加鉴权 / 限制内网访问。</p><p><strong>我的项目关联</strong> 我们服务是 Docker 容器部署的，actuator 主要用于给容器编排提供 <strong>health 探针</strong>（<strong>存活/就绪检查</strong>），服务不健康能自动重启。<strong>通用坑</strong>：生产上不能把所有端点直接暴露出去，env、beans 会泄露配置和内部结构，我们只开 health，其余要么不开、要么限内网加<strong>鉴权</strong>。这是通用安全做法，不是我们踩过的坑，但规范上必须守住。</p><p><strong>面试答题话术</strong> 「<strong>actuator</strong> 是应用监控探针，引 starter 就暴露<strong>端点</strong>。常用的：health <strong>健康检查</strong>、metrics 指标、env 环境、beans、loggers 动态改日志级别。默认只暴露 health 和 info，其他要显式配置 include 打开。生产上一定要加<strong>鉴权</strong>，env、beans 这种不能裸奔。项目里主要用 health 做容器探活，只开放 health，其他端点不开或限内网。」</p><hr><h2 id="_41-什么是-mybatis-★★★" tabindex="-1">41. 什么是 MyBatis ★★★ <a class="header-anchor" href="#_41-什么是-mybatis-★★★" aria-label="Permalink to &quot;41. 什么是 MyBatis ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> MyBatis 是一个<strong>半自动的 ORM（持久层）框架</strong>，它把 SQL 和 Java 代码<strong>解耦</strong>：SQL 写在 XML 或注解里，查询结果自动映射成 Java 对象（POJO）。核心特点：① SQL 完全由开发者手写，<strong>可控</strong>、可优化；② 通过 XML/注解维护 SQL 和<strong>映射关系</strong>；③ 支持<strong>动态 SQL</strong>（if/foreach/where 等标签）；④ <strong>轻量、无侵入</strong>、不强制继承框架类。对比<strong>全自动 ORM</strong>（如 Hibernate），它不自动生成 SQL，所以叫「半自动」。</p><p><strong>我的项目关联</strong> 我们后端服务是 JDK 21 + SpringBoot + MyBatis-Plus（MyBatis 的增强）做<strong>持久层</strong>，大量用 <strong>BaseMapper</strong>、IService、<strong>分页插件</strong>。复杂查询（对账、统计、按条件查订单）手写 SQL 放 XML，简单单表 CRUD 用 MyBatis-Plus 直接做，不写<strong>样板 SQL</strong>。这样既可控又省事。</p><p><strong>面试答题话术</strong> 「MyBatis 是<strong>半自动 ORM 框架</strong>，SQL 手写、结果自动映射成对象。特点是 SQL 可控、支持<strong>动态 SQL</strong>、<strong>轻量无侵入</strong>。对比<strong>全自动 ORM</strong> 它不生成 SQL，所以叫半自动。项目里我用 MyBatis-Plus 做持久层，复杂查询手写 XML，简单 CRUD 用 BaseMapper。」</p><hr><h2 id="_42-mybatis-与-jdbc、hibernate-的区别-★★★" tabindex="-1">42. MyBatis 与 JDBC、Hibernate 的区别 ★★★ <a class="header-anchor" href="#_42-mybatis-与-jdbc、hibernate-的区别-★★★" aria-label="Permalink to &quot;42. MyBatis 与 JDBC、Hibernate 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>JDBC</strong>：最底层，手写连接、PreparedStatement、ResultSet，还要自己管理连接、异常、资源关闭，<strong>样板代码</strong>极多。MyBatis：在 JDBC 上封装了连接管理、<strong>参数映射</strong>、<strong>结果映射</strong>，SQL 还是要自己写，但样板代码大幅减少，SQL 可控。Hibernate：<strong>全自动 ORM</strong>，用 HQL/对象操作自动生成 SQL，开发快，但复杂查询、性能调优不可控，学习成本高。一句话：JDBC 是「手动挡」，MyBatis 是「半自动」，Hibernate 是「全自动」。</p><p><strong>我的项目关联</strong> 选 MyBatis（MyBatis-Plus）就是因为业务里大量复杂查询（对账、统计、条件筛选订单）需要 <strong>SQL 可控</strong>、能<strong>精确调优</strong>，Hibernate 生成 SQL 不可控不适合我们。而 MyBatis-Plus 又补上了单表 CRUD 的便捷性，兼顾了两头。这是<strong>选型理由</strong>，面试可以直接讲。</p><p><strong>面试答题话术</strong> 「<strong>JDBC</strong> 最底层，连接、参数、结果全手写，<strong>样板代码</strong>多；MyBatis 封装了连接管理和<strong>结果映射</strong>，SQL 还是自己写，可控；Hibernate <strong>全自动</strong>生成 SQL，开发快但复杂查询不可控。一句话：JDBC 手动挡、MyBatis 半自动、Hibernate 全自动。项目里选 MyBatis-Plus 就是因为对账、统计这种复杂查询要 SQL 可控，又能用 BaseMapper 省掉单表样板代码。」</p><hr><h2 id="_43-为什么说-mybatis-是半自动-orm-★★★" tabindex="-1">43. 为什么说 MyBatis 是半自动 ORM ★★★ <a class="header-anchor" href="#_43-为什么说-mybatis-是半自动-orm-★★★" aria-label="Permalink to &quot;43. 为什么说 MyBatis 是半自动 ORM ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 判断<strong>全自动</strong>还是<strong>半自动</strong>，看「SQL 谁来写、<strong>对象关系映射</strong>谁来做」：MyBatis 帮你做了「<strong>结果映射</strong>」这一半（查询结果自动映射成 Java 对象），但「SQL 生成」这一半要你自己写（写 XML/注解）。所以它是「半自动」。Hibernate 两半都自动（SQL 由框架生成），所以叫<strong>全自动 ORM</strong>；JDBC 两半都手动，压根不算 ORM。</p><p><strong>我的项目关联</strong> 我们实际就是「<strong>半自动</strong>」的用法：SQL 全部自己写（复杂查询放 XML），<strong>映射</strong>交给框架。这样复杂 join、聚合、分页、调优都能<strong>精确控制</strong>，同时不用手写 ResultSet 映射的样板代码。</p><p><strong>面试答题话术</strong> 「半自动就是：<strong>结果映射</strong>这一半框架帮你做，<strong>SQL 生成</strong>这一半要自己写。Hibernate 是两半都自动所以叫<strong>全自动</strong>，JDBC 两半都手写不算 <strong>ORM</strong>，MyBatis 卡在中间。我们项目里就是 SQL 自己写、映射交给框架，复杂查询能精确调优，又不用写 ResultSet 样板。」</p><hr><h2 id="_44-mybatis-的适用场景-★★☆" tabindex="-1">44. MyBatis 的适用场景 ★★☆ <a class="header-anchor" href="#_44-mybatis-的适用场景-★★☆" aria-label="Permalink to &quot;44. MyBatis 的适用场景 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 适合：① SQL 需要<strong>精细控制</strong>、<strong>性能调优</strong>的场景；② <strong>复杂查询</strong>多（多表 join、动态条件、报表统计）；③ 团队 SQL 能力强、想保留 SQL <strong>自主权</strong>；④ 老系统数据库结构复杂、ORM 自动映射搞不定的。不适合：① 业务 CRUD 简单、对象模型清晰，<strong>全自动 ORM</strong> 更快；② 团队不想碰 SQL。一句话：SQL 复杂、要可控，选 MyBatis。</p><p><strong>我的项目关联</strong> 我们的场景高度契合：充电业务里对账、交易统计、按多条件查订单，SQL 复杂且要<strong>精确调优</strong>，手写 SQL 最合适。同时用 MyBatis-Plus 把<strong>简单单表 CRUD</strong> 也提了效，等于「复杂 SQL 手写 + 简单 CRUD 自动」，<strong>兼顾两端</strong>。</p><p><strong>面试答题话术</strong> 「适合 SQL 要<strong>精细控制</strong>、<strong>复杂查询</strong>多、团队 SQL 能力强的场景；不适合 CRUD 简单、对象模型清晰、不想写 SQL 的场景。我们的充电业务里对账、统计、条件查订单都是复杂 SQL，需要<strong>精确调优</strong>，所以选 MyBatis，再用 MyBatis-Plus 把简单 CRUD 也提速了。」</p><hr><h2 id="_45-mybatis-核心组件有哪些-sqlsessionfactory、sqlsession、executor、statementhandler-等-★★★" tabindex="-1">45. MyBatis 核心组件有哪些（SqlSessionFactory、SqlSession、Executor、StatementHandler 等）★★★ <a class="header-anchor" href="#_45-mybatis-核心组件有哪些-sqlsessionfactory、sqlsession、executor、statementhandler-等-★★★" aria-label="Permalink to &quot;45. MyBatis 核心组件有哪些（SqlSessionFactory、SqlSession、Executor、StatementHandler 等）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 核心组件是一条链：① <code>SqlSessionFactoryBuilder</code>：读配置构建 SqlSessionFactory，用完就丢；② <code>SqlSessionFactory</code>：全局唯一、<strong>线程安全</strong>，负责生产 SqlSession；③ <code>SqlSession</code>：一次数据库会话，<strong>非线程安全</strong>，执行 SQL 的<strong>门面</strong>；④ <code>Executor</code>：真正执行器，负责缓存、事务、Statement 处理，有 Simple/Reuse/Batch 三种；⑤ <code>StatementHandler</code>：处理 JDBC Statement，做参数设置和<strong>结果映射</strong>；⑥ <code>ParameterHandler</code> / <code>ResultSetHandler</code>：分别设参数、映射结果；⑦ <code>TypeHandler</code>：Java 类型和 JDBC 类型互转；⑧ <code>MappedStatement</code>：封装一条 SQL 的所有信息（SQL、参数、返回值）；⑨ <code>Interceptor</code>：<strong>插件机制</strong>，在 Executor、StatementHandler 等关键点做动态代理拦截。</p><p><strong>我的项目关联</strong> 这些组件不用背源码，但「<strong>一条链</strong>」要能串起来讲，因为面试爱问<strong>执行链路</strong>。最直接的关联：MyBatis-Plus 的<strong>分页插件</strong>就是 Interceptor，拦在 Executor 这一环改写 SQL 拼 LIMIT。知道这个对应关系，就能把组件串起来讲。</p><p><strong>面试答题话术</strong> 「核心组件是一条链：SqlSessionFactoryBuilder 读配置建 SqlSessionFactory，工厂生产 SqlSession，SqlSession 是执行 SQL 的<strong>门面</strong>、<strong>非线程安全</strong>，真正干活的是 <strong>Executor</strong>，负责缓存和事务，再往下 <strong>StatementHandler</strong> 处理 Statement，<strong>ParameterHandler</strong> 设参数、<strong>ResultSetHandler</strong> 映射结果，TypeHandler 做类型互转，<strong>MappedStatement</strong> 封装一条 SQL 的所有信息。插件 Interceptor 就是在 Executor、StatementHandler 这些位置做<strong>动态代理拦截</strong>，MyBatis-Plus 分页插件拦的就是 Executor。」</p><hr><h2 id="_46-mapper-接口为什么不需要实现类-动态代理原理-★★★" tabindex="-1">46. Mapper 接口为什么不需要实现类（动态代理原理）★★★ <a class="header-anchor" href="#_46-mapper-接口为什么不需要实现类-动态代理原理-★★★" aria-label="Permalink to &quot;46. Mapper 接口为什么不需要实现类（动态代理原理）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 你只定义了 Mapper 接口、没写实现类，却能直接注入调用，靠的是 <strong>JDK 动态代理</strong>：MyBatis 启动时用 <strong>MapperProxyFactory</strong> 给每个 Mapper 接口生成一个<strong>代理对象</strong>（<strong>MapperProxy</strong>），它实现 <strong>InvocationHandler</strong>。调用 <code>mapper.xxx()</code> 时，代理的 invoke 方法拿到「接口全限定名 + 方法名」组成 <strong>statementId</strong>，去 Configuration 里找到对应的 <strong>MappedStatement</strong>，再交给 SqlSession 执行 SQL。所以「接口没有实现类，<strong>代理类就是实现</strong>」。这也解释了为什么 Mapper 接口方法不能<strong>重载</strong>（statementId 会冲突）、为什么 Mapper 必须是 interface。</p><p><strong>我的项目关联</strong> 我们用 MyBatis-Plus 时 <strong>BaseMapper</strong> 也是这个原理，自定义 Mapper 继承 BaseMapper 就有<strong>通用 CRUD</strong>。<strong>通用坑</strong>：Mapper 接口方法不能<strong>重载</strong>——有人给一个 Mapper 写两个同名不同参的方法，XML 里只有一个 statementId，结果运行时报「找不到映射」。这是通用坑，写的时候注意别重载。面试问「Mapper 为什么不用写实现类」就答动态代理。</p><p><strong>面试答题话术</strong> 「Mapper 接口没有实现类，靠 <strong>JDK 动态代理</strong>。MyBatis 启动时给每个 Mapper 接口生成一个 <strong>MapperProxy</strong>，实现 InvocationHandler。调用时 invoke 拿到接口名加方法名组成 <strong>statementId</strong>，去 Configuration 找到对应 <strong>MappedStatement</strong>，交给 SqlSession 执行。所以代理类就是实现类。这也是 Mapper 方法不能<strong>重载</strong>的原因，因为 statementId 会冲突。项目里 MyBatis-Plus 的 BaseMapper 也是这个原理，自定义 Mapper 继承它就有<strong>通用 CRUD</strong>。」</p><hr><h2 id="_47-mybatis-有几种-executor-执行器-★★☆" tabindex="-1">47. MyBatis 有几种 Executor 执行器 ★★☆ <a class="header-anchor" href="#_47-mybatis-有几种-executor-执行器-★★☆" aria-label="Permalink to &quot;47. MyBatis 有几种 Executor 执行器 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 三种：① <code>SimpleExecutor</code>（默认）：每次执行都创建新的 Statement，用完关闭；② <code>ReuseExecutor</code>：复用 Statement（按 SQL 缓存复用，重复执行同一条 SQL 不重复创建）；③ <code>BatchExecutor</code>：<strong>批量执行</strong>，把所有 update 攒起来<strong>批量提交</strong>，适合<strong>批量插入</strong>。还有个 CachingExecutor 是<strong>包装器</strong>（开启二级缓存时包在真执行器外面）。SpringBoot 里默认 SimpleExecutor，全局配置 <code>mybatis.executor-type=batch</code> 可改。</p><p><strong>我的项目关联</strong> 我们默认用 SimpleExecutor，因为一次请求基本就执行一两条 SQL，没必要复用或批量。<strong>通用坑</strong>：<strong>大批量导入</strong>、<strong>对账落库</strong>这种场景，SimpleExecutor 一条一条 insert 很慢，正确做法是换 BatchExecutor、或用 MyBatis-Plus 的 saveBatch / <strong>批量插入</strong>、甚至一次性 insert 多条。这是通用坑，值得提一嘴，别傻乎乎逐条插。</p><p><strong>面试答题话术</strong> 「Executor 三种：Simple 默认、每次新建 Statement；Reuse <strong>复用</strong> Statement；Batch <strong>攒批处理</strong>，适合<strong>批量更新</strong>。SpringBoot 默认 Simple。项目里默认 Simple 够用，但<strong>批量导入</strong>、<strong>对账落库</strong>这种场景要换成 Batch 或用<strong>批量插入</strong>，不能逐条 insert，太慢。」</p><hr><h2 id="_48-mybatis-工作流程-完整执行链路-★★★" tabindex="-1">48. MyBatis 工作流程（完整执行链路）★★★ <a class="header-anchor" href="#_48-mybatis-工作流程-完整执行链路-★★★" aria-label="Permalink to &quot;48. MyBatis 工作流程（完整执行链路）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>完整链路</strong>八步：① 启动时读 mybatis 配置 + Mapper XML，解析成 Configuration（含 MappedStatement）；② 拿到 <strong>SqlSessionFactory</strong>，再开 <strong>SqlSession</strong>；③ 调用 Mapper 接口方法 → <strong>MapperProxy</strong> <strong>动态代理拦截</strong>；④ 用「接口名.方法名」定位 <strong>MappedStatement</strong>；⑤ SqlSession 交给 Executor 执行；⑥ Executor 先查<strong>一级缓存</strong>，未命中交给 <strong>StatementHandler</strong>；⑦ StatementHandler 用 ParameterHandler 设参数（#{} 预编译），执行 SQL，再用 ResultSetHandler 映射结果；⑧ 结果回填，SqlSession 关闭清一级缓存。插件 Interceptor 在 ⑤⑥⑦ 各环节可拦截。</p>',188)),(r(),g(e,null,{default:t(()=>[a(s,{id:"mermaid-655",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BMapper%20%E6%96%B9%E6%B3%95%5D%20--%3E%20B%5BMapperProxy%3Cbr%2F%3E%E5%8A%A8%E6%80%81%E4%BB%A3%E7%90%86%E6%8B%A6%E6%88%AA%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%AE%9A%E4%BD%8D%20MappedStatement%5D%0A%20%20%20%20C%20--%3E%20D%5BSqlSession%5D%0A%20%20%20%20D%20--%3E%20E%5BExecutor%3Cbr%2F%3E%E6%9F%A5%E4%B8%80%E7%BA%A7%E7%BC%93%E5%AD%98%5D%0A%20%20%20%20E%20--%3E%20F%5BStatementHandler%3Cbr%2F%3EParameterHandler%20%E8%AE%BE%E5%8F%82%5D%0A%20%20%20%20F%20--%3E%20G%5B%E6%89%A7%E8%A1%8C%20SQL%5D%0A%20%20%20%20G%20--%3E%20H%5BResultSetHandler%3Cbr%2F%3E%E6%98%A0%E5%B0%84%E7%BB%93%E6%9E%9C%5D%0A"})]),fallback:t(()=>o[1]||(o[1]=[i(" Loading... ")])),_:1})),o[4]||(o[4]=n('<p><strong>我的项目关联</strong> 这条<strong>链路</strong>面试必问，最好一口气串下来。关联到项目：MyBatis-Plus 的<strong>分页插件</strong>就是拦在 Executor 这一环，把原始 SQL 包一层、拼上 LIMIT 再执行；<strong>一级缓存</strong>也是这条链路里查的。理解链路后，前面「一级缓存脏数据」「分页插件原理」都能串成一个<strong>体系</strong>，不用死记。</p><p><strong>面试答题话术</strong> 「工作流程：启动解析配置和 Mapper XML 生成 <strong>Configuration</strong>；开 <strong>SqlSession</strong>；调用 Mapper 方法走<strong>动态代理</strong>，用接口名加方法名定位 <strong>MappedStatement</strong>；交给 <strong>Executor</strong> 执行，先查<strong>一级缓存</strong>，未命中再给 <strong>StatementHandler</strong>；StatementHandler 用 ParameterHandler 设参、执行 SQL、<strong>ResultSetHandler</strong> 映射结果，最后回填。插件就是在 Executor、StatementHandler 这些环节拦截，MyBatis-Plus 分页插件就是拦 Executor 拼 LIMIT，一级缓存也是这条链路里查的，串起来就都通了。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li>Spring Test：<code>@SpringBootTest</code> 起容器、<code>@MockBean</code> 打桩，写<strong>集成测试</strong>用。</li><li><code>@ControllerAdvice</code> 与 <code>@RestControllerAdvice</code>：后者是前者的 <strong>ResponseBody 版本</strong>，返回 <strong>JSON</strong> 用它。</li></ul>',5))])}const C=p(l,[["render",S]]);export{M as __pageData,C as default};
